import {installStudioReader} from './studio-upgrade.js';
import {ReaderWorkbench} from './reader.js';
import {$,$$,esc,pretty,badge,btn,empty,metric,fmtDate,toast,api,modal,closeModal,confirm,form,jsonEditor,showJSON,showDiff,showError,upload,onJobDone,submitJob,settingsDialog,jobsDialog,bindActions,objectBody,lightbox,resumeProjectJobs} from './common.js';
document.documentElement.style.setProperty('--accent','#edbd82');document.documentElement.style.setProperty('--accent2','#393024');
const STAGES=[['B0','原稿与场次','Ingest'],['B1','风格与改编','Treatment'],['B2','视觉资产','Assets'],['B3','场景导演','Direction'],['B4','分镜设计','Shot List'],['B5','素材生成','Render'],['B6','声音与剪辑','Assembly']];
const KINDS={style:'风格包',master:'主资产',variant:'资产变体',asset_state:'资产时间状态',scene:'场次',direction:'导演方案',shot:'镜头',transition:'转场',link:'衔接依赖',foreshadow:'伏笔资产'};
const state={projectId:new URLSearchParams(location.search).get('project')||localStorage.getItem('system-b-project'),projects:[],data:null,stage:'B0',sceneId:null,shotId:null,view:'reader',health:null,schemas:null,renderKind:'keyframe',quality:'proxy',runner:'',audio:[],subtitles:[],silence:[],allowAnimatic:false,keepOriginalAudio:false,checked:new Set(),proposalFilter:'latest'};
const reader=new ReaderWorkbench({system:'B',state,refresh:()=>refresh(),advanced:context=>{state.view='stages';state.stage=context?.stage||'B4';if(context?.sceneId)state.sceneId=context.sceneId;render()},selectProject:async id=>{state.projectId=id;state.selected=null;state.sceneId=null;state.shotId=null;state.checked?.clear();await refresh()}});
installStudioReader(reader);
const P=path=>`/api/projects/${state.projectId}${path}`;const scenes=()=>state.data?.scenes.filter(s=>s.status!=='archived')||[];const shots=()=>state.data?.shots.filter(s=>s.status!=='archived')||[];const scene=()=>scenes().find(s=>s.id===state.sceneId);const shot=()=>shots().find(s=>s.id===state.shotId);const masterName=id=>state.data?.masters.find(a=>a.id===id)?.name||id;const sceneName=id=>scenes().find(s=>s.id===id)?.title||id;
function localAssembly(){if(!state.projectId)return;const x=state.data?.project.assemblyDraft||JSON.parse(localStorage.getItem('assembly-'+state.projectId)||'{}');state.audio=x.audio||[];state.subtitles=x.subtitles||[];state.silence=x.silence||[]}
async function saveAssembly(){const assemblyDraft={audio:state.audio,subtitles:state.subtitles,silence:state.silence};localStorage.setItem('assembly-'+state.projectId,JSON.stringify(assemblyDraft));await api(P(''),'PUT',{assemblyDraft})}
async function refresh(){state.projects=await api('/api/projects');if(!state.projects.find(p=>p.id===state.projectId))state.projectId=state.projects[0]?.id||null;if(state.projectId){state.data=await api(P(''));state.jobs=await api('/api/jobs?project='+encodeURIComponent(state.projectId));resumeProjectJobs(state.jobs);if(!scenes().some(s=>s.id===state.sceneId))state.sceneId=scenes()[0]?.id||null;const current=shots().filter(s=>s.sceneId===state.sceneId);if(!current.some(s=>s.id===state.shotId))state.shotId=current[0]?.id||null;localStorage.setItem('system-b-project',state.projectId)}else state.data=null;render()}
function shell(content){return `<aside class="sidebar"><div class="brand"><div class="brand-mark">B</div><div><div class="brand-name">FRAMELAB</div><div class="eyebrow">Director System</div></div></div>${btn('new','＋ 新建视听项目','primary')}<div class="nav-separator">制作工作空间</div>${btn('reader','阅读与选择','nav-button')}${STAGES.map(([s,t])=>btn('stage',`<span class="mono">${s}</span><span>${t}</span>`,'nav-button '+(state.stage===s&&state.view==='stages'?'active':''),`data-stage="${s}"`)).join('')}<div class="nav-separator">运行与管理</div>${btn('runners','⌘ 执行器与路由','nav-button '+(state.view==='runners'?'active':''))}${btn('audit','◷ 成本与操作记录','nav-button '+(state.view==='audit'?'active':''))}<div class="nav-separator">我的项目</div><div class="projects">${state.projects.map(p=>`<div class="project-item ${p.id===state.projectId?'active':''}" data-action="project" data-id="${p.id}"><span class="project-dot"></span><span class="truncate">${esc(p.title)}</span></div>`).join('')}</div><div class="sidebar-footer">${btn('settings','⚙ 模型 / 媒体服务','nav-button')}<div>独立数据库 · 不依赖 System A</div></div></aside><main class="main"><header class="topbar"><div><div class="topbar-title">${esc(state.data?.project.title||'视听导演工作室')}</div><div class="topbar-subtitle">SYSTEM B · 改呈现，不擅自改故事</div></div><span class="mode-pill ${state.health?.mode==='demo'?'demo':''}">${state.health?.mode==='demo'?'演示推理 · 非真实模型':'直接模型推理'}</span><div class="topbar-actions">${btn('reader','阅读工作台','tiny')}${btn('new','＋ 新建','ghost tiny')}${btn('restore-backup','恢复备份','tiny')}${btn('jobs','任务','tiny')}${state.data?btn('exports','导出','tiny')+btn('project-settings','项目设置','tiny'):''}${btn('settings','连接设置','tiny')}</div></header><div class="content" id="page-content">${content}</div></main>`}
function render(){document.getElementById('app').classList.toggle('reader-active',state.view==='reader');if(state.view==='reader'){reader.mount();return;}let html;if(!state.data)html=welcome();else if(state.view==='runners'||state.view==='audit')html='<div class="skeleton"></div>';else html=stageHead()+({'B0':ingest,'B1':treatment,'B2':assets,'B3':direction,'B4':shotlist,'B5':renderView,'B6':assembly}[state.stage])();$('#app').innerHTML=shell(html);if(state.view==='runners')loadRunners();if(state.view==='audit'&&state.data)loadAudit();bindInputs()}
function welcome(){return `<div class="page-head"><div><div class="eyebrow accent" style="margin-bottom:12px">AUDIOVISUAL DIRECTOR + PRODUCER</div><h1>把故事，变成能生成、能剪接的视听作品。</h1><p>从原稿、场景、资产到镜头和声音，保留每一道人工闸口。</p></div></div><div class="grid cols3" style="margin-bottom:24px">${metric('B0 — B2','原稿 · 风格 · 资产定稿')}${metric('B3 — B5','导演 · 分镜 · 关键帧与视频')}${metric('B6','声音 · 剪辑 · 成片验收')}</div>${empty('开始独立制作','可直接输入小说或剧本；也可导入 System A 的 SceneExport 文件，但不需要运行 A。',btn('new','创建视听项目','primary'))}<div class="callout" style="max-width:820px;margin:24px auto">内置本地测试卡与视频用于验证完整链路，不是 AI 生成效果。实际生图、生视频需配置媒体接口，或在外部生成后导入。</div>`}
function doneStage(s){return s==='B0'?scenes().length:s==='B1'?state.data.style.status==='locked':s==='B2'?state.data.masters.some(a=>a.status==='locked'):s==='B3'?state.data.directions.some(d=>d.status==='accepted'||d.status==='locked'):s==='B4'?shots().length:s==='B5'?state.data.renders.some(r=>r.selected):state.data.assemblys.some(a=>a.status==='accepted')}
function stageHead(){const current=STAGES.find(s=>s[0]===state.stage);const cost=state.data.cost;return `<div class="stage-rail">${STAGES.map(([s,t,en])=>btn('stage',`<strong>${s} ${t}</strong><small>${en}</small>`,'stage '+(state.stage===s?'active ':'')+(doneStage(s)?'done':''),`data-stage="${s}"`)).join('')}</div><div class="page-head"><div><div class="eyebrow" style="margin-bottom:7px">${current[0]} / ${current[2]}</div><h1>${current[1]}</h1></div><div class="row"><span class="badge">累计费用 $${Number(cost.spent).toFixed(3)}</span>${cost.reserved?badge('opportunity','已预留 $'+cost.reserved):''}${badge(state.data.style.status,'风格 '+(state.data.style.status==='locked'?'已定稿':'待定稿'))}</div></div>`}
function sceneSelector(){return `<div class="row" style="margin-bottom:18px"><label for="scene-select" style="margin:0;white-space:nowrap">当前场次</label><select id="scene-select" style="max-width:440px">${scenes().map(s=>`<option value="${s.id}" ${s.id===state.sceneId?'selected':''}>${s.order+1}. ${esc(s.title)} · ${s.targetDuration==null?'时长待节奏方案':s.targetDuration+'s'}</option>`).join('')}</select>${scene()?badge(scene().freshness):''}</div>`}
function props(stage){let all=state.data.proposals.filter(p=>p.stage===stage&&(!p.sceneId||p.sceneId===state.sceneId));if(state.proposalFilter!=='all'){const pending=all.filter(x=>x.status==='proposed');all=pending.length?pending.slice(-2):all.slice(-1)}return all}
function proposalTray(stage){const rows=props(stage);return rows.length?`<section class="panel" style="margin-top:20px"><div class="row between"><h3>待审提案</h3>${btn('proposal-history',state.proposalFilter==='all'?'最新提案':'全部历史','tiny')}</div>${rows.map(p=>`<div class="list-row"><div class="grow"><h4>${stage==='B4'?`镜头骨架 · ${p.payload.shots?.length||0} 镜`:stage==='B0'?`归一化场次 · ${p.payload.scenes?.length||0} 场`:stage==='B2'?`资产提取 · ${p.payload.assets?.length||0} 项`:stage==='B3'?'逐场导演方案':'改编与全片曲线'}</h4><p>${fmtDate(p.createdAt)}${p.demo?' · 离线演示提案':''} · ${esc(p.id.slice(-8))}</p></div>${badge(p.status)}${btn('proposal-view','预览','tiny',`data-id="${p.id}"`)}${p.status==='proposed'?btn('proposal-adopt','采纳','tiny primary',`data-id="${p.id}"`)+btn('proposal-reject','拒绝','tiny',`data-id="${p.id}"`):''}</div>`).join('')}</section>`:''}
function ingest(){return `<div class="grid cols2"><section class="panel"><div class="row between"><h3>输入原稿</h3><div class="row">${btn('upload-source','导入文本','tiny')}${btn('import-a','导入 SceneExport','tiny')}</div></div><textarea id="source-text" rows="13" placeholder="粘贴小说或剧本。">${esc(state.data.project.source)}</textarea><div class="row" style="margin-top:14px">${btn('save-source','保存原稿')}${btn('propose','归一化为场次提案','primary','data-stage="B0"')}<small>不自动采纳</small></div></section><section class="panel"><h3>显式改编决策</h3><p class="muted smalltext">小说的内心、概述、叙述视角和时长密度需要留下处理记录。平段是改编工单，不是自动删除指令。</p><div class="stack">${[['内心独白','外化为行为 / VO / 对白 / 删除'],['概述段落','蒙太奇 / 单镜象征 / 展开场景 / 删除'],['叙述视角','限知跟随 / 全知 / 主观段落'],['信息密度','重新分配目标时长']].map(([t,d])=>`<div class="list-row"><div><h4>${t}</h4><p>${d}</p></div></div>`).join('')}</div></section></div>${proposalTray('B0')}<section style="margin-top:24px"><div class="row between"><h3>正式场次表 · ${scenes().length} 场</h3>${btn('add-scene','＋ 手工场次','tiny')}</div><div class="stack">${scenes().map(s=>`<article class="panel"><div class="row between"><div><small>SCENE ${String(s.order+1).padStart(2,'0')}</small><h3 style="margin:4px 0">${esc(s.title)}</h3></div><div>${s.flat?badge('opportunity','平段工单'):''}${badge(s.status)} ${btn('edit-scene','编辑 / 决策','tiny',`data-id="${s.id}"`)}</div></div><p class="prose smalltext" style="margin-top:12px">${esc(s.sourceText?.slice(0,700))}</p><div class="row"><small>${esc(s.location)} · ${esc(s.timeOfDay)} · ${s.targetDuration==null?'时长待节奏方案':s.targetDuration+'s'}</small>${badge('draft',s.tensionType)}${(s.flatFlags||[]).map(f=>badge('opportunity',f)).join('')}</div></article>`).join('')||empty('尚未采纳场次','输入原稿后，先预览并采纳归一化提案。')}</div></section>`}
function treatment(){const st=state.data.style;const curves=state.data.project.curves||[];return `<div class="callout" style="margin-bottom:20px">风格包是雪崩级对象。ASL、镜头数、画幅变化会影响全片设计；定稿后修改会先显示影响和成本。Prompt 前缀微调只影响未来渲染。</div><div class="grid cols3">${Object.entries(state.schemas?.presets||{}).map(([k,v])=>`<article class="card ${st.preset===k?'selected':''}"><div class="card-label">${k.toUpperCase()}</div><h2>${esc(v.name)}</h2><div class="stat">${v.aslRange[0]}–${v.aslRange[1]}<small> 秒 / 镜</small></div><div class="stack" style="margin:18px 0"><small>建议每场 ${v.shotCountRange.join('–')} 镜，按内容调整</small><small>空镜 ${v.emptyShotRatio.map(n=>Math.round(n*100)).join('–')}%</small><small>画幅由你选择 · ${esc(v.movementAmplitude)}</small><small>信息间隔 ${v.informationInterval.join('–')}s</small></div>${btn('preset',st.preset===k?'当前风格':'应用此档','',`data-key="${k}"`)}</article>`).join('')}</div><section class="panel" style="margin-top:20px"><div class="row between"><h3>风格参数与冻结</h3><div class="row">${btn('edit-style','调整参数 / 前缀')}${btn('finalize','人工定稿风格包','primary',`data-kind="style" data-id="${st.id}"`)}</div></div><div class="grid cols2"><div><small>色彩</small><p>${esc(st.palette)}</p><small>质感与光比</small><p>${esc(st.texture)} · ${esc(st.lightingRatio)}:1</p></div><div><small>编译前缀</small><p class="smalltext mono">${esc(st.promptPrefix)}</p><small>负面词</small><p class="smalltext mono">${esc(st.negativePrompt)}</p></div></div></section><div class="row" style="margin-top:24px">${btn('propose','生成改编与节奏曲线提案','primary','data-stage="B1"')}${btn('add-transition','＋ 场间转场')}${btn('edit-curves','编辑时长曲线')}</div>${proposalTray('B1')}<section class="panel" style="margin-top:20px"><h3>全片情绪与节奏</h3>${curveSvg(curves)}<div class="table-wrap"><table><thead><tr><th>场次</th><th>进入 → 转折 → 退出</th><th>目标时长</th></tr></thead><tbody>${curves.map(c=>`<tr><td>${esc(sceneName(c.sceneId))}</td><td>${c.entry} → ${c.turn} → ${c.exit}</td><td>${c.targetDuration}s</td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><h3>场间转场 · 双向约束</h3>${state.data.transitions.filter(t=>t.status!=='archived').map(t=>`<div class="list-row"><div class="grow"><h4>${esc(sceneName(t.fromScene))} → ${esc(sceneName(t.toScene))}</h4><p>${esc(t.type)}</p></div>${badge(t.freshness)}${btn('edit-object','编辑两端约束','tiny',`data-kind="transition" data-id="${t.id}"`)}</div>`).join('')||'<small>尚未生成场间转场。</small>'}</section>`}
function curveSvg(curves){if(!curves.length)return '<p class="muted smalltext">先采纳 B1 提案，再看全片曲线。</p>';const values=curves.flatMap(c=>[Number(c.entry),Number(c.turn),Number(c.exit)]);const pts=values.map((v,i)=>`${20+i*760/Math.max(1,values.length-1)},${130-v*11}`).join(' ');return `<svg width="100%" height="155" viewBox="0 0 800 155" aria-label="情绪曲线"><path d="M20 130H780M20 75H780M20 20H780" stroke="#303d48" fill="none"/><polyline points="${pts}" fill="none" stroke="#edbd82" stroke-width="2.5"/>${values.map((v,i)=>`<circle cx="${20+i*760/Math.max(1,values.length-1)}" cy="${130-v*11}" r="3" fill="#edbd82"/>`).join('')}</svg>`}
function assets(){const masters=state.data.masters.filter(a=>a.status!=='archived');return `${sceneSelector()}<div class="row" style="margin-bottom:18px">${btn('propose','提取资产候选','primary','data-stage="B2"')}${btn('add-asset','＋ 添加资产')}${btn('add-state','＋ 状态时间区间')}${btn('add-foreshadow','＋ 伏笔资产')}${btn('manifests','场次资产清单')}</div>${proposalTray('B2')}<div class="media-grid" style="margin-top:20px">${masters.map(a=>{const variants=state.data.variants.filter(v=>v.masterId===a.id);const v=variants.find(v=>v.id===a.defaultVariantId);const file=state.data.files.find(f=>f.id===(v?.referenceFileId||a.referenceFileId));const options=state.data.assetOptions.filter(o=>o.assetId===a.id&&o.status==='proposed');return `<article class="card media-card">${file?`<img class="thumb portrait" src="${esc(file.url)}" alt="${esc(a.name)}" data-action="lightbox" data-url="${esc(file.url)}">`:`<div class="thumbnail-empty">尚未确认参考图</div>`}<div class="row between" style="margin-top:12px"><h3 style="margin:0">${esc(a.name)}</h3>${badge(a.status)}</div><small>${{character:'角色基准',location:'场景 Plate',prop:'道具基准'}[a.kind]} · seed ${a.seed}</small><p class="smalltext" style="margin-top:10px">${esc(a.freezeString.slice(0,160))}</p><div class="row">${btn('asset-generate','生成参考图','tiny',`data-id="${a.id}"`)}${btn('asset-upload','导入参考','tiny',`data-id="${a.id}"`)}${btn('asset-edit','编辑','tiny',`data-id="${a.id}"`)}</div><div class="card-footer">${btn('finalize','人工定稿','tiny primary',`data-kind="master" data-id="${a.id}"`)}${btn('asset-variants',`${variants.length} 个变体`,'tiny',`data-id="${a.id}"`)}</div>${options.length?`<div class="stack" style="margin-top:12px">${options.slice(-3).map(o=>`<div><img class="thumb" src="${esc(o.url)}" alt="资产候选" data-action="lightbox" data-url="${esc(o.url)}">${btn('asset-option','采用此参考','tiny',`data-id="${o.id}"`)}</div>`).join('')}</div>`:''}</article>`}).join('')}</div>${!masters.length?empty('先建立稳定的视觉身份','每个主资产有冻结串和固定 seed。临时变化通过 Variant 与 AssetState 管理，不改基准身份。'):''}<div class="grid cols2" style="margin-top:24px"><section class="panel"><h3>资产状态时间轴</h3>${state.data.asset_states.map(s=>`<div class="list-row"><div class="grow"><strong>${esc(masterName(s.assetId))}</strong><p>${esc(sceneName(s.validFrom))} → ${s.validUntil?esc(sceneName(s.validUntil)):'持续到结束'}<br>${esc(state.data.variants.find(v=>v.id===s.variantId)?.name)}</p></div>${btn('edit-object','编辑','tiny',`data-kind="asset_state" data-id="${s.id}"`)}</div>`).join('')||'<small>受伤、服装、道具状态由区间自动解析。</small>'}</section><section class="panel"><h3>伏笔资产</h3>${state.data.foreshadows.map(f=>`<div class="list-row"><div class="grow"><strong>${esc(masterName(f.assetId))}</strong><p>${esc(f.foreshadowRole||'setup/payoff')} · ${esc(sceneName(f.setupSceneId))} → ${esc(sceneName(f.payoffSceneId))}</p></div>${btn('edit-object','编辑','tiny',`data-kind="foreshadow" data-id="${f.id}"`)}</div>`).join('')||'<small>埋设不直给特写；回收复用指定变体。</small>'}</section></div>`}
function direction(){const s=scene();const d=state.data.directions.find(d=>d.sceneId===s?.id&&d.status!=='archived');return `${sceneSelector()}${!s?empty('先采纳场次表','从 B0 开始归一化输入。'): `<div class="row" style="margin-bottom:18px">${btn('propose','生成本场导演方案','primary','data-stage="B3"')}${btn('manual-direction','手填导演方案')}${d?btn('edit-object','调整现有方案','',`data-kind="direction" data-id="${d.id}"`)+btn('finalize','关键场人工定稿','',`data-kind="direction" data-id="${d.id}"`):''}</div><div class="panel"><small>本场原稿 / 已采纳呈现</small><p class="prose smalltext" style="margin-top:8px">${esc(s.presentation||s.sourceText)}</p><div class="row">${badge('draft',s.tensionType)}<small>目标 ${s.targetDuration==null?'时长待节奏方案':s.targetDuration+'s'}</small></div></div>${proposalTray('B3')}${d?`<div class="grid cols2" style="margin-top:22px"><section class="panel"><div class="row between"><h3>戏剧与信息</h3>${badge(d.status)}${badge(d.freshness)}</div><p>${esc(d.dramaticFunction)}</p><div class="value-change"><span>${d.emotion.entry}</span><span>→ ${d.emotion.turn} →</span><span>${d.emotion.exit}</span><small>${esc(d.tensionType)}</small></div><hr><small>必须传达</small>${d.informationPayload.map(x=>`<p class="smalltext" style="margin-top:5px">${esc(x)}</p>`).join('')}<small>覆盖策略</small><p class="smalltext">${esc(typeof d.coverage==='object'?d.coverage.master:pretty(d.coverage))}</p></section><section class="panel"><h3>调度 · 光 · 声</h3>${objectBody({blocking:d.blocking,lighting:d.lighting,palette:d.palette,sound:d.sound})}</section></div>`:empty('本场如何被看见？','导演方案决定信息如何揭示、人物怎么移动、光从哪里来、何时安静。')}`}`}
function shotlist(){const s=scene();const rows=shots().filter(x=>x.sceneId===state.sceneId);return `${sceneSelector()}${s?`<div class="row" style="margin-bottom:18px">${btn('propose','生成镜头骨架候选','primary','data-stage="B4"')}${btn('validate','连续性校验')}${btn('add-link','＋ 镜间依赖')}${btn('exports','导出分镜表')}</div><div class="callout info">两段式分镜：先审景别、运镜和一句动作，再由程序计算时长、轴线、视线、光位、资产变体及生成风险。Prompt 编译不调用模型。</div>${proposalTray('B4')}<section class="panel" style="margin-top:20px"><div class="row between"><h3>本场正式镜头 · ${rows.length} 镜</h3><small>${rows.reduce((n,s)=>n+s.duration,0).toFixed(3)} / ${s.targetDuration==null?'时长待节奏方案':s.targetDuration+'s'}</small></div><div class="table-wrap"><table><thead><tr><th>#</th><th>景别 / 运镜</th><th>行动与信息</th><th>时长</th><th>风险</th><th>操作</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${String(i+1).padStart(2,'0')}<br>${badge(x.freshness)}</td><td><strong>${x.shotSize}</strong> · ${x.angle}<br><small>${x.lens}mm · ${x.movement.type} / ${x.movement.speed}</small></td><td style="min-width:260px">${esc(x.actionLine)}<p class="muted smalltext">${esc(x.informationPayload.join('；'))}</p></td><td>${x.duration.toFixed(3)}s</td><td>${badge(x.producibilityRisk.score>.5?'opportunity':'clean',Math.round(x.producibilityRisk.score*100)+'%')}<br><small>${esc(x.producibilityRisk.recommendation||'')}</small></td><td><div class="row">${btn('edit-shot','调整','tiny',`data-id="${x.id}"`)}${btn('render-shot','去生成','tiny',`data-id="${x.id}"`)}${btn('compile','Prompt','tiny',`data-id="${x.id}"`)}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><h3>镜间生成依赖</h3>${state.data.links.filter(l=>l.status!=='archived').map(l=>`<div class="list-row"><div class="grow"><strong>${shotLabel(l.from)} → ${shotLabel(l.to)}</strong><p>${esc(l.type)}${['frame_chain','extension','ref_video'].includes(l.type)?' · 有向强依赖':' · 可并行 / 成对设计'}</p></div>${btn('edit-object','编辑','tiny',`data-kind="link" data-id="${l.id}"`)}</div>`).join('')||'<small>默认 cut，无媒体依赖。frame_chain / extension / ref_video 绑定实际上游媒体。</small>'}</section>`:empty('缺少场次','先完成 B0。')}`}
function shotLabel(id){const s=shots().find(x=>x.id===id);return s?`${esc(sceneName(s.sceneId))} / ${s.order+1}`:esc(id)}
function renderView(){const s=scene();const row=shots().filter(x=>x.sceneId===state.sceneId);const rshot=shot();let rs=state.data.renders.filter(r=>r.shotId===state.shotId&&r.kind===state.renderKind);return `${sceneSelector()}${rshot?`<div class="grid media-workbench"><aside class="panel outline"><h3>本场镜头</h3>${row.map(x=>`<div class="tree-node ${x.id===state.shotId?'active':''}" data-action="select-shot" data-id="${x.id}"><div class="row"><input type="checkbox" data-shot-check="${x.id}" ${state.checked.has(x.id)?'checked':''}><strong>${String(x.order+1).padStart(2,'0')} · ${x.shotSize}</strong><small>${x.duration.toFixed(1)}s</small></div><p class="smalltext muted" style="margin:5px 0">${esc(x.actionLine.slice(0,54))}</p>${badge(x.freshness)}${state.data.renders.some(r=>r.shotId===x.id&&r.selected&&r.kind===state.renderKind)?badge('clean','已终选'):''}</div>`).join('')}<hr>${btn('check-all','全选本场','tiny')}${btn('check-none','清空','tiny')}<p class="muted smalltext" style="margin-top:12px">选中多镜后可批量预估和生成。强依赖上游未验收会明确阻塞。</p></aside><section class="stack"><div class="panel"><div class="row between"><div><h3>镜头 ${rshot.order+1} · ${rshot.shotSize} / ${rshot.angle}</h3><small>${esc(rshot.actionLine)}</small></div>${btn('compile','查看编译 Prompt','tiny',`data-id="${rshot.id}"`)}</div><hr><div class="row"><select id="render-kind" style="width:auto"><option value="keyframe" ${state.renderKind==='keyframe'?'selected':''}>关键帧静图</option><option value="clip" ${state.renderKind==='clip'?'selected':''}>视频片段</option></select><select id="render-quality" style="width:auto"><option value="proxy" ${state.quality==='proxy'?'selected':''}>低清代理物</option><option value="final" ${state.quality==='final'?'selected':''}>正式素材</option></select><select id="runner-select" style="width:auto"><option value="">按路由</option>${Object.entries(state.data.runners).map(([id,p])=>`<option value="${esc(id)}" ${state.runner===id?'selected':''}>${esc(id)}${p.enabled?'':'（未启用）'}</option>`).join('')}</select></div><div class="row" style="margin-top:14px">${btn('render-dry','预估 → 确认生成','primary')}${btn('import-render','导入已有素材')}${btn('retry-render','有界重试 / 换抽卡')}${btn('circuit-reset','复位熔断','ghost tiny')}</div></div><div class="row between"><h3 style="margin:0">候选素材 · ${rs.length} 份</h3><div class="row"><small>比较候选，选定本镜采用版本</small>${btn('shortlist','保存短名单','tiny')}</div></div><div class="media-grid">${rs.map(r=>`<article class="card media-card ${r.selected?'selected':''}">${r.kind==='clip'?`<video class="thumb" src="${esc(r.url)}" preload="metadata" controls></video>`:`<img class="thumb portrait" src="${esc(r.url)}" alt="关键帧候选" data-action="lightbox" data-url="${esc(r.url)}">`}<div class="row between" style="margin-top:10px"><label class="checkbox-row"><input type="checkbox" data-shortlist="${r.id}" ${r.shortlisted?'checked':''}>短名单</label><small>${r.quality==='proxy'?'代理物':'正式'}</small></div><div class="row" style="margin-top:6px">${badge(r.freshness)}${r.pinned?badge('pinned'):''}${r.demo?badge('opportunity','测试素材'):''}${badge(r.gate?.status||r.gateStatus||'review')}</div><div class="row" style="margin-top:12px">${btn('select-render',r.selected?'已终选':'复核并终选','tiny '+(r.selected?'':'primary'),`data-id="${r.id}"`)}${btn('pin-render',r.pinned?'解除 Pin':'Pin','tiny',`data-id="${r.id}"`)}${btn('gate-report','门禁','tiny',`data-id="${r.id}"`)}${btn('media-detail','溯源','tiny',`data-id="${r.id}"`)}</div></article>`).join('')}</div>${!rs.length?empty('这个镜头还没有素材','先生成低清关键帧，确认身份、构图和信息，再投入视频。也可导入外部生成工具的结果。'):''}</section></div>`:empty('先完成分镜设计','采纳 B4 镜头骨架后才能编译 Prompt 并生成媒体。',btn('stage','前往 B4','primary','data-stage="B4"'))}`}
function assembly(){const selected=state.data.renders.filter(r=>r.selected);const arts=state.data.assemblys;return `<div class="callout info" style="margin-bottom:20px">这里只装配你已采用的素材，不触发任何生图或生视频。声音轨、字幕时间和静默点可编辑，成片仍需人工验收。</div><div class="stat-grid">${metric(shots().length,'正式镜头')}${metric(selected.filter(r=>r.kind==='keyframe').length,'已选关键帧')}${metric(selected.filter(r=>r.kind==='clip').length,'已选视频')}${metric(shots().reduce((n,s)=>n+s.duration,0).toFixed(1)+'s','分镜时长合计')}</div><section class="panel" style="margin-top:20px"><div class="row between"><h3>画面剪辑轨</h3>${btn('assembly-view','查看装配计划','tiny')}</div><div class="track">${shots().map(s=>`<div class="track-item" style="width:${Math.max(90,s.duration*25)}px" data-action="render-shot" data-id="${s.id}"><strong>${String(s.order+1).padStart(2,'0')} · ${s.shotSize}</strong><p style="margin:6px 0 0">${s.duration.toFixed(2)}s</p><small>${esc(sceneName(s.sceneId).slice(0,8))}</small></div>`).join('')}</div><div class="row" style="margin-top:15px"><label class="checkbox-row"><input id="allow-animatic" type="checkbox" ${state.allowAnimatic?'checked':''}>允许缺失视频时用终选静图做预演</label><label class="checkbox-row"><input id="keep-audio" type="checkbox" ${state.keepOriginalAudio?'checked':''}>保留视频原声</label></div></section><div class="grid cols2" style="margin-top:20px"><section class="panel"><div class="row between"><h3>声音轨</h3>${btn('add-audio','＋ 导入声音','tiny')}</div>${state.audio.map((t,i)=>`<div class="list-row"><div class="grow"><strong>${esc(t.name||t.kind||'音频轨')}</strong><p>${t.start}s 开始 · 音量 ${t.gain} · 淡入 ${t.fadeIn||0}s / 淡出 ${t.fadeOut||0}s</p></div>${btn('edit-audio','编辑','tiny',`data-index="${i}"`)}${btn('delete-audio','移除','tiny danger',`data-index="${i}"`)}</div>`).join('')||'<small>上传对白、旁白、音乐或音效。音频来源不会自动猜测。</small>'}</section><section class="panel"><div class="row between"><h3>字幕与静默</h3><div class="row">${btn('edit-subtitles','编辑字幕','tiny')}${btn('import-subtitles','导入 SRT','tiny')}${btn('edit-silence','静默点','tiny')}</div></div><p class="muted smalltext">${state.subtitles.length} 条字幕 · ${state.silence.length} 处静默。字幕以 MP4 可选字幕轨导出，并保留 SRT 文件。</p>${state.subtitles.slice(0,4).map(s=>`<p class="smalltext">${s.start}–${s.end}s · ${esc(s.text)}</p>`).join('')}</section></div><div class="row" style="margin-top:20px">${btn('assemble','预览并输出成片','primary')}${btn('assembly-draft-save','保存剪辑草案')}</div>${arts.length?`<section class="panel" style="margin-top:24px"><h3>成片版本与验收</h3><div class="grid cols2">${arts.slice().reverse().map(a=>`<article class="card"><video class="thumb" src="${esc(a.url)}" controls preload="metadata">${a.webVttFile?`<track default kind="subtitles" srclang="zh" label="中文" src="${esc(a.webVttFile.url)}">`:""}</video><div class="row between" style="margin-top:12px"><div>${badge(a.status)}${a.isAnimatic?badge('opportunity','静帧预演'):''}</div><small>${fmtDate(a.createdAt)}</small></div><div class="row" style="margin-top:15px">${btn('accept-film','人工验收','tiny primary',`data-id="${a.id}"`)}<a href="/api/files/${a.fileId}/download" target="_blank">下载 MP4 ↗</a>${btn('film-plan','剪辑记录','tiny',`data-id="${a.id}"`)}</div></article>`).join('')}</div></section>`:''}`}
function proposalHtml(p){const x=p.payload;if(p.stage==='B0')return `<div class="stack">${x.scenes.map((s,i)=>`<div class="panel"><h3>${i+1}. ${esc(s.title)}</h3><div class="prose smalltext">${esc(s.sourceText)}</div><hr><small>${esc(s.location)} · ${s.targetDuration==null?'时长待节奏方案':s.targetDuration+'s'} · ${esc(s.tensionType)}</small><pre>${esc(pretty(s.narrativeHandling))}</pre></div>`).join('')}</div>`;if(p.stage==='B4')return `<div class="callout info">这里先审创意骨架。采纳后程序会填完镜头时长、光位、资产、轴线和风险，并再次校验。</div><div class="stack" style="margin-top:18px">${x.shots.map((s,i)=>`<div class="panel"><div class="row between"><h3>${i+1}. ${s.shotSize} · ${s.angle}</h3><small>${s.movement?.type} / ${s.movement?.speed}</small></div><p class="prose smalltext">${esc(s.actionLine)}</p><small>${esc(s.informationPayload?.join('；'))}</small></div>`).join('')}</div>`;if(p.stage==='B3')return `<div class="grid cols2"><div class="panel">${objectBody({dramaticFunction:x.dramaticFunction,emotion:x.emotion,informationPayload:x.informationPayload,coverage:x.coverage})}</div><div class="panel">${objectBody({blocking:x.blocking,lighting:x.lighting,sound:x.sound,palette:x.palette,targetDuration:x.targetDuration})}</div></div>`;if(p.stage==='B2')return `<div class="grid cols2">${x.assets.map(a=>`<div class="panel"><small>${esc(a.kind)}</small><h3>${esc(a.name)}</h3><p>${esc(a.freezeString)}</p>${badge(a.requiresImage?'opportunity':'clean',a.requiresImage?'需要独立参考图':'可用描述变体')}</div>`).join('')}</div>`;return `<div class="stack">${x.adaptations.map(a=>`<div class="panel"><h3>${esc(sceneName(a.sceneId))}</h3><small>${esc(a.strategy)}</small><p class="prose smalltext">${esc(a.presentation)}</p></div>`).join('')}</div>${curveSvg(x.curves)}`}
async function saveObject(kind,obj){let data={object:obj};const old=obj.id?objectBy(kind,obj.id):null;if(old?.status==='locked'){const plan=await api(P(`/objects/${kind}/plan`),'POST',data);if(!await confirm('已定稿对象变更 · '+KINDS[kind],impactHtml(plan),'确认修改',plan.costLevel==='avalanche'))return;data.planHash=plan.planHash}const r=await api(P('/objects/'+kind),'POST',data);await refresh();return r}
function objectBy(kind,id){return (state.data[kind+'s']||[]).find(x=>x.id===id)||((kind==='style'&&state.data.style.id===id)?state.data.style:null)}
function impactHtml(plan){return `<div class="callout ${plan.costLevel==='avalanche'?'danger':'info'}">${plan.costLevel==='avalanche'?'雪崩级身份变更':plan.costLevel==='future_only'?'非身份变更，仅未来渲染受影响':'局部依赖变更'}。这里只标记失效，不自动付费重生成。</div><p style="margin-top:15px">${plan.items.length} 个受影响对象 · ${plan.pinnedConflicts} 个 Pin 仲裁 · 历史估计重生成 $${plan.estimatedRegenerationCost}</p><pre>${esc(pretty(plan.items))}</pre>`}
async function editScene(s){const d=await form('场次与小说决策',[{name:'title',label:'场次名称',required:true},{name:'location',label:'地点'},{name:'timeOfDay',label:'时段'},...(s?.targetDuration!=null?[{name:'targetDuration',label:'本场时长（秒）',type:'number',min:1}]:[]),{name:'tensionType',label:'张力类型',type:'select',options:['suspense','surprise','mystery']},{name:'sourceText',label:'原稿 / 场次文本',type:'textarea',rows:6},{name:'presentation',label:'改编后的呈现（不改故事）',type:'textarea',rows:4},{name:'payloadText',label:'必须传达的信息，每行一条',type:'textarea',rows:3},{name:'inner',label:'内心独白决策',type:'select',options:['不需要','外化为行为/道具/环境','VO','对白','删除']},{name:'summary',label:'概述段落决策',type:'select',options:['不需要','蒙太奇','单镜象征','展开场景','删除']},{name:'pov',label:'叙述视角',type:'select',options:['限知跟随','全知','主观镜头']}],{...s,payloadText:s?.informationPayload?.join('\n')||'',inner:s?.narrativeHandling?.innerMonologue?.decision||'不需要',summary:s?.narrativeHandling?.summary?.decision||'不需要',pov:s?.narrativeHandling?.pov?.decision||'限知跟随',targetDuration:s?.targetDuration??null});if(!d)return;const value={...s,...d,targetDuration:d.targetDuration??s?.targetDuration??null,informationPayload:d.payloadText.split('\n').filter(Boolean),narrativeHandling:{innerMonologue:{needed:d.inner!=='不需要',decision:d.inner},summary:{needed:d.summary!=='不需要',decision:d.summary},pov:{decision:d.pov}},order:s?.order??scenes().length,characters:s?.characters||[],props:s?.props||[],locationId:s?.locationId||null,characterNames:s?.characterNames||['主角'],flatness:s?.flatness||{}};for(const k of ['payloadText','inner','summary','pov'])delete value[k];await saveObject('scene',value)}
async function editAsset(a){const d=await form(a?'编辑主资产':'添加主资产',[{name:'name',label:'名称',required:true},{name:'kind',label:'类别',type:'select',options:[{value:'character',label:'人物'},{value:'location',label:'场景 Plate'},{value:'prop',label:'道具'}]},{name:'freezeString',label:'冻结描述串（编译时原样注入）',type:'textarea',rows:6,required:true},{name:'identity',label:'身份定义：脸 / 发型 / 体型 / 标志性服装',type:'json',rows:5},{name:'seed',label:'固定 seed',type:'number',min:0}],a||{kind:'character',identity:{face:'',hair:'',body:'',wardrobe:''},seed:Math.floor(Math.random()*1000000)});if(d)await saveObject('master',{...a,...d})}
async function renderDry(data={}){const params={shotIds:state.checked.size?[...state.checked]:[state.shotId],kind:state.renderKind,quality:state.quality,...(state.runner?{runner:state.runner}:{}),...data};const plan=await api(P('/render/dry-run'),'POST',params);const html=`<div class="stat-grid">${metric(plan.newRenders,'需要新生成')}${metric(plan.requests.length-plan.newRenders,'缓存复用')}${metric(plan.videoSeconds+'s','视频总秒数')}${metric('$'+plan.estimatedCost,'预计媒体成本')}</div>${plan.blocked.length?`<div class="callout danger" style="margin-top:18px">存在阻塞项，不会提交生成。</div><pre>${esc(pretty(plan.blocked))}</pre>`:''}<p class="muted smalltext" style="margin-top:16px">${esc(plan.runner)} · ${params.quality} · Runner 身份不进入 renderKey。外部已提交任务取消后仍可能计费。</p>`;if(plan.blocked.length){modal('生成预估：尚不能执行',html,'',true);return}if(await confirm('确认本批生成',html,'提交生成')){await submitJob(P('/render/execute'),{...params,planHash:plan.planHash});await refresh()}}
function assemblyParams(){return {audio:state.audio,subtitles:state.subtitles,silence:state.silence,allowAnimatic:state.allowAnimatic,keepOriginalAudio:state.keepOriginalAudio,quality:'final',fps:24}}
async function addAudio(t,index){if(!t){const f=await upload(state.projectId,'audio/*');if(!f)return;t={fileId:f.id,name:f.filename,kind:'music',start:0,offset:0,gain:.6,fadeIn:1,fadeOut:1}}const d=await form('声音轨参数',[{name:'name',label:'轨道名称'},{name:'kind',label:'声音类型',type:'select',options:[{value:'music',label:'音乐'},{value:'dialogue',label:'对白'},{value:'vo',label:'旁白 VO'},{value:'sfx',label:'音效'},{value:'ambience',label:'环境声'}]},{name:'start',label:'成片进入点（秒）',type:'number',step:.1,min:0},{name:'offset',label:'音源截取起点（秒）',type:'number',step:.1,min:0},{name:'duration',label:'使用时长（秒，0 = 到全片结束）',type:'number',step:.1,min:0},{name:'gain',label:'音量倍率',type:'number',step:.05,min:0},{name:'fadeIn',label:'淡入秒数',type:'number',step:.1,min:0},{name:'fadeOut',label:'淡出秒数',type:'number',step:.1,min:0}],{...t,duration:t.duration||0});if(d){const value={...t,...d};if(!value.duration)delete value.duration;if(index===undefined)state.audio.push(value);else state.audio[index]=value;saveAssembly().catch(showError);render()}}
async function loadRunners(){const x=await api('/api/runners');if(state.view!=='runners')return;$('#page-content').innerHTML=`<div class="page-head"><div><h1>可插拔执行器</h1><p>推理不经过 Agent CLI。执行器只负责已确定的媒体任务，并被幂等壳、预算和隔离约束。</p></div>${btn('routing','编辑路由','primary')}</div><div class="callout" style="margin-bottom:20px">默认先用受信任 subprocess。Pi / Codex / 第三方必须声明隔离方式（Docker 容器，或显式选择无隔离的本机直连）并通过 12 项验收。只切换 Runner 不会令缓存失效。</div><div class="grid cols3">${Object.entries(x.profiles).map(([id,p])=>`<article class="panel"><div class="row between"><h2>${esc(id)}</h2>${badge(p.enabled?'clean':'draft',p.enabled?'已启用':'未启用')}</div><p class="muted">${esc(p.kind)} · adapter ${esc(p.adapterVersion)}</p><div class="stack"><small>隔离：${esc(p.sandbox?.type||'受信任内置代码')}${p.sandbox?.type==='host'?'（本机直连，无操作系统隔离）':''}</small><small>并发 ${p.limits.maxConcurrency} · 超时 ${p.limits.defaultTimeout}s</small>${badge(x.qualification[id]?'clean':'opportunity',x.qualification[id]?'验收通过':'未通过生产验收')}</div><div class="card-footer">${btn('runner-edit','配置','tiny',`data-id="${id}"`)}${btn('runner-qualify','执行 12 项验收','tiny',`data-id="${id}"`)}${btn('runner-report','报告','tiny',`data-id="${id}"`)}</div></article>`).join('')}</div><section class="panel" style="margin-top:20px"><h3>当前路由</h3><pre>${esc(pretty(x.routing))}</pre><p class="muted smalltext">优先级：单次手动指定 → overrides → roles。默认关闭自动 fallback，避免不可预期账单。</p></section>${state.data?.curator_items.length?`<section class="panel" style="margin-top:20px"><h3>自愈 Prompt 差异 / 模板缺陷队列</h3>${state.data.curator_items.map(c=>`<div class="list-row"><div class="grow"><strong>${esc(c.taskId)}</strong><p>${esc(c.status)}</p></div>${btn('curator','审阅差异','tiny',`data-id="${c.id}"`)}</div>`).join('')}</section>`:''}`;state.runnerData=x}
async function loadAudit(){const [history,runs]=await Promise.all([api(P('/history')),api(P('/runner-runs'))]);if(state.view!=='audit')return;const cost=state.data.cost,recoverable=runs.filter(r=>r.result?.remote?.submitId&&r.result?.status!=='ok');$('#page-content').innerHTML=`<div class="page-head"><div><h1>成本、版本与执行证据</h1><p>保留任务、实际 Prompt、seed、产物、模型成本和 Runner provenance。</p></div>${btn('model-runs','模型推理记录')}</div><div class="stat-grid">${metric('$'+cost.spent,'媒体已记账')}${metric('$'+cost.reserved,'媒体已预留')}${metric(cost.unknown,'待对账失败调用')}${metric(runs.length,'Runner 实际执行')}</div>${recoverable.length?`<div class="panel" style="margin-top:22px"><h3>可恢复的远程媒体任务</h3><p class="muted smalltext">恢复只查询原 submit_id 并下载，不会重新提交收费任务。</p>${recoverable.map(r=>`<div class="list-row"><div class="grow"><strong>${esc(r.task?.task||'媒体生成')} · ${esc(r.result.remote.submitId)}</strong><p>${esc(r.result.report?.notes||r.result.remote.status||'等待远程结果')}</p></div>${btn('runner-detail','证据','tiny',`data-id="${r.id}"`)}${btn('recover-media','查询并恢复','tiny primary',`data-id="${r.id}"`)}</div>`).join('')}</div>`:''}<div class="panel" style="margin-top:22px"><h3>不可变操作日志</h3>${history.slice(-80).reverse().map(h=>`<div class="list-row"><div class="grow"><strong>${esc(h.op)}</strong><p>${esc(h.scope?.join(' · ')||'项目')}</p></div><small>${fmtDate(h.created)}</small>${btn('audit-detail','详情','tiny',`data-id="${h.id}"`)}</div>`).join('')}</div>`;state.history=history;state.runnerRuns=runs}
function bindInputs(){if($('#scene-select'))$('#scene-select').onchange=e=>{state.sceneId=e.target.value;state.shotId=shots().find(s=>s.sceneId===state.sceneId)?.id;state.checked.clear();render()};if($('#render-kind'))$('#render-kind').onchange=e=>{state.renderKind=e.target.value;render()};if($('#render-quality'))$('#render-quality').onchange=e=>state.quality=e.target.value;if($('#runner-select'))$('#runner-select').onchange=e=>state.runner=e.target.value;$$('[data-shot-check]').forEach(c=>{c.onclick=e=>e.stopPropagation();c.onchange=()=>{if(c.checked)state.checked.add(c.dataset.shotCheck);else state.checked.delete(c.dataset.shotCheck)}});if($('#allow-animatic'))$('#allow-animatic').onchange=e=>state.allowAnimatic=e.target.checked;if($('#keep-audio'))$('#keep-audio').onchange=e=>state.keepOriginalAudio=e.target.checked}
